quests[81632] = { id = 81632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echsen ergreifen", description = "Auch wenn wir uns auf einem Strafposten befinden, ist das Leben hier nicht ganz unangenehm. Dank Kapitänin Lancekat haben wir einen großzügigen Vorrat an Proviant. \n\nHatten wir zumindest bis vor Kurzem. Eine große Echse hat sich mit unseren Lagervorräten davongemacht!\n\nKönntet Ihr unsere Vorräte zurückholen und den Dieb erledigen?", sourceObjective = "Erlegt Müffelschuppe und bergt 8 Lagervorräte.", progress = "Habt Ihr die Vorräte gefunden?", completion = "Sehr gut. Wir werden mit diesen Vorräten ein Festmahl veranstalten und auf Euren Erfolg anstoßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81638] = { id = 81638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuhause ist, wo der Ruhestein ist", sourceObjective = "Willkommen in unserem bescheidenen Dorf.\n\nIch kann Euch einen Ruhestein geben, damit Ihr jederzeit hierher zurückkehren könnt, wenn Ihr einen Ort zum Ausruhen braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[81639] = { id = 81639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honig stehlende Neruber" }
quests[81640] = { id = 81640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenir und der Orden der Nacht", description = "<Das Skript für ein episches Bühnenstück. Inspizientin Huberta auf der Insel von Dorn könnte daran Interesse haben.>", sourceObjective = "Bringt dies zu Inspizientin Huberta auf der Insel von Dorn.\n\nBereitgestellter Gegenstand:", completion = "Höchst interessant. Das kommt auf den Stapel für ungelesene Einreichungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81647] = { id = 81647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Titanischer Rückstrom" }
