quests[81650] = { id = 81650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Titanischer Rückstrom" }
quests[81651] = { id = 81651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefgehender Tiefenratgeber", description = "Grüße! Seid Ihr für ein paar Tiefenexpeditionen in der Umgebung zu haben?", sourceObjective = "Erreicht den Erdsturz und die Mykomantenhöhle.", sourceObjectiveStatus = "unverified-source-field" }
quests[81653] = { id = 81653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shurrai, Grässlichkeit des Untermeers" }
quests[81654] = { id = 81654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vorbotin", description = "Wir benötigen erneut Eure Hilfe, Champion. Eine geheimnisvolle Gestalt schleicht durch die Schatten. Die Vorbotin...\n\nSprechen wir in der Kammer des Wächters. Ich habe Alleria gebeten, uns ebenfalls dort zu treffen.", sourceObjective = "Trefft Khadgar und Alleria an der Kammer des Wächters in Dalaran.", progress = "Ein strahlender Gesang, ein dunkles Herz und diese geheimnisvolle Vorbotin... Was kann das alles nur bedeuten?", completion = "Wir wissen, dass Iridikron das dunkle Herz der Vorbotin übergab. Aber was das dunkle Herz ist und was die Vorbotin damit vorhat... das alles ist noch unbekannt.\n\nUnd der strahlende Gesang. Der Zeitpunkt ist kein Zufall.\n\nDiese Angelegenheit kann nicht länger warten. Darum habe ich Euch und Alleria gebeten, dies zu untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81655] = { id = 81655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saftiges Kroluskfleisch", description = "Seid gegrüßt! Ich bin Kagfritha. Ich war einst Aufseherin in der Grollenden Einöde südlich von hier, aber die Zeit hat unserem Unterfangen stark zugesetzt und wir mussten das Gebiet verlassen.\n\nEs ist höchste Zeit, dass wir die Dinge dort wieder in Ordnung bringen, aber in unserer Abwesenheit sind einige widerwärtige Kreaturen aufgetaucht. Ich habe einen Plan, wie wir mit den schlimmsten von ihnen fertig werden, aber zuerst brauchen wir einen Köder.\n\nWenn Ihr helfen wollt, dann geht auf die Jagd nach diesen dreckigen Krolusken und bringt mir ihr Fleisch.", sourceObjective = "Sammelt 4 Stücke Kroluskfleisch.", progress = "Ich habe große Pläne für dieses Kroluskfleisch, und für die Grollende Einöde!", completion = "Ah, diese saftigen Fleischbrocken sind genau das, was ich brauche!", sourceObjectiveStatus = "unverified-source-field" }
quests[81656] = { id = 81656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts zu verschwenden" }
quests[81661] = { id = 81661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Trauerhöhe", description = "Seid gegrüßt, Fremdling. Ich heiße Urtago, und ich bin Verwalter Korgrans Lehrling an der Gedächtnisstätte Trauerhöhe.\n\nDiese hinterhältigen kerzenerhellten Kobolde haben die Trauerhöhe überrannt, und wir brauchen Hilfe. Würdet Ihr Euch mit mir am Fallsprungaußenposten treffen? Er liegt direkt nördlich von hier. Ich kann Euch mehr erzählen, sobald Ihr dort eintrefft.", sourceObjective = "Trefft Euch mit Urtago am Fallsprungaußenposten.", completion = "Da seid Ihr ja! Danke, dass Ihr gekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[81667] = { id = 81667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Emporkömmling", description = "Ihr seid die \"ungebundene Drittpartei\"? Ausgezeichnet. Ihr seid der perfekte Katalysator für einen Coup.\n\nDie Stadt der Fäden hat einen Emporkömmling hergeschickt, um die Kontrolle über Rah-Ahat zu erlangen. \n\nDie Ankunft Ren'khats hat alles durcheinandergebracht. Er spielt sich als eine Art städtischer Visionär der Seide auf und fordert die Autorität der Hochspinnerin heraus, die sich weigerte, ihre Herrschaft aufzugeben. \n\nSchlecht für die Hochspinnerin, gut für uns. Sprecht mit Ren'khat und nährt seinen Ehrgeiz. Helft ihm, sich gegen die Hochspinnerin durchzusetzen.", sourceObjective = "Bietet Ren'khat Eure Dienste gegen die große Hochspinnerin Antourix an.", completion = "Ihr ... Ihr wollt mir helfen, die Brillianz meiner Kunst zu realisieren? \n\nUnd Ihr habt keine Verbindungen, die wieder auf mich zurückfallen könnten? \n\nPerfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[81668] = { id = 81668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einmal Maß nehmen, dreimal schneiden", description = "Als ich die Stadt verließ, um nach Rak-Ahat zu gehen, wurde mir eine wichtige, glanzvolle und beneidenswerte Position versprochen.\n\nDiese Lagerhausarbeit hingegen ist weder wichtig noch beneidenswert. Und ganz bestimmt nicht glanzvoll.\n\nDie große Hochspinnerin Antourix ist schon viel zu lange an der Macht. Sie versteht meine Vision nicht. Alles, was sie will, sind Handlanger, die genau das tun, was wie will und wie sie es will.\n\nSchaltet ihre loyalsten Arbeiterinnen aus. Wir werden sehen, wie gut sie sich schlägt, wenn sie ganz allein ist und ich die Färberei übernehme.", sourceObjective = "Tötet Netzverzerrerin Tath'rhiz, Flözschnitterin Zhir'ix und Farbenbeschwörerin Nirethi.", completion = "Wenn diese Kriecher aus dem Weg sind, ist die Hochspinnerin ein Nichts. Dann habe ich hier im Handumdrehen das Sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81669] = { id = 81669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stock und Knochen", description = "Während die Kroluske am liebsten aus dem Untergrund angreifen, treibt sich in der Grollenden Einöde auch ein Raubtier herum, das sich von oben auf seine Beute stürzt. Tiefenschinder haben auf den Gipfeln und Kämmen in der Einöde ihre Nester gebaut.\n\nZerstört ihre Nester und zeigt ihnen, dass sie in der Einöde nicht willkommen sind.", sourceObjective = "Verbrennt 6 Tiefenschindernester.", completion = "Ich konnte den Rauch bis hierhin sehen! Gute Arbeit! Damit sollten die grässlichen Viecher verstehen, dass sie sich lieber anderswo niederlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81670] = { id = 81670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerrissene Seide", description = "Nichts erregt die Aufmerksamkeit der Kopfabschneiderin und stört sie bei ihrer Arbeit so sehr wie die Zerstörung ihrer Ausrüstung! Geht rein und bringt alles durcheinander, sendet wirklich eine Botschaft." }
quests[81672] = { id = 81672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Klemme", description = "Ich sollte wohl reinen Tisch machen und Euch erklären, warum Ihr das Fleisch sammeln solltet.\n\nDie Wahrheit ist, in der Einöde haust eine entsetzliche Bestie. Ein Monster, das jeden verspeist, der unvorsichtig war, mit Kneifzangen, die durch Gestein und Knochen schneiden wie ein Messer durch warme Butter.\n\nEs heißt Smaragthr, und das niederträchtige Biest ist auch der Grund, weshalb ich nur ein Auge habe und meine Edelsteine gesprungen sind. Ich habe keine Chance gegen so ein Monster, aber Ihr... Ihr könntet Rache für mich üben.\n\nTötet Smaragthr, damit die Einöde frei ist.", sourceObjective = "Tötet Smaragthr.", progress = "Ich werde an der grässlichen Kreatur Rache üben!", completion = "Ihr habt es geschafft! Ich hoffe, es hat gelitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[81673] = { id = 81673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrung Eurer Anstrengungen", description = "Auch wenn ich nur einen bescheidenen Rang habe, erweise ich Euch diese Ehre. Ein Zunderkasten, der für Eure Freundschaft mit unserer Expedition und Euren hochverehrten Status in Heilsturz steht.\n\nSolltet Ihr im Kampf fallen, bekommt Euer Zunderkasten einen Ehrenplatz unter denen der anderen großen Helden, die bei der Verteidigung dieses Landes gestorben sind.\n\nBitte nehmt diese Ehre an.", sourceObjective = "Nehmt die Ehre eines Zunderkastens von Heilsturz an.", completion = "Möge die Heilige Flamme Euch beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81675] = { id = 81675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schafe tränken" }
quests[81683] = { id = 81683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühjahrskollektion", description = "Diese Made Ren'khat hat es auf meine Position abgesehen? Soll er nur kommen und versuchen, sie mir wegzunehmen.\n\nAll die Reste unserer Operation fließen in die Quelle unter Rak-Ahat. Ein jahrzehntelanger Zufluss von Beizmitteln, Katalysatoren und alchemistischem Gebräu hat etwas... Mächtiges geschaffen.\n\nKümmert Euch nicht um die Nebenwirkungen. Bringt mir einfach eine Vielzahl verschiedener Farbstoffe, und ich werde Farben zusammenrühren, die euch ein paar neue Beine verleihen.", sourceObjective = "Sammelt 12 zurückgewonnene Katalysatoren sowie 3 leuchtende Würgersäfte, 3 augenlose Blüten und 3 Karminkriecher.", progress = "Ihr seid noch da?", completion = "Ich denke, das wird ausreichen. Ihr seid doch nicht so nutzlos, wie ich dachte.", sourceObjectiveStatus = "unverified-source-field" }
quests[81685] = { id = 81685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azj-Kahets nächster Top-Färbemeister", description = "Ren'khat und die Hochspinnerin kämpfen mit Klaue und Schere. In der Spinndrüse. Ohne Zeugen.\n\nWir haben hier eine einmalige Gelegenheit. Sollten sie sich gegenseitig umbringen, nun ja... Da Antourix' Günstlinge nicht hier sind und in ganz Rak-Ahat Chaos herrscht, wäre die nächstbeste Autorität der Karawanenkoordinator. Und das bin ich.\n\nIch stehe zwar nicht gern im Rampenlicht, aber es wäre für unsere geheime Schmuggeloperation sehr von Vorteil, wenn die zwei es nicht aus der Färberei herausschaffen würden.", sourceObjective = "Tötet Ren'khat und die große Hochspinnerin Antourix.", completion = "Dieser absolute Skandal wird die Archivare in der Stadt der Fäden monatelang beschäftigen.\n\nUnd ich werde dafür sorgen, dass sie nicht zu genau hinschauen, wie er zustande gekommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[81686] = { id = 81686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trickbetrug in Seide", description = "Ich erwarte eine Lieferung Seide. Dass sie nicht eingetroffen ist, bereitet mir Sorgen.\n\nDie meiste Seide in Azj-Kahet, vom feinsten Schleier bis hin zur stärksten Kriegsseide, stammt aus Rak-Ahat, was den Ort zu einem nützlichen Geflecht aus Informationen macht.\n\nEine Spionin schmuggelt für mich Militärgeheimnisse, die in die Seide eingewoben sind. Kürzlich berichtete sie mir von einem Machtkampf in Rak-Ahat... und seit neuestem erhalte ich überhaupt keine Berichte mehr von ihr.\n\nTrefft Euch mit ihr und stellt sicher, dass es nicht mehr zu Verzögerungen kommt.", sourceObjective = "Trefft Euch mit Teth in Rak-Ahat.", completion = "Wie ich sehe, hat unser „Freund“ meine Nachricht erhalten und Euch zu Hilfe gerufen.\n\nUnser Produktionsplan ist hinfällig, weil die Verwaltung sich nicht durchsetzen kann.\n\nVermutlich ist dieses Chaos fruchtbarer Boden für ihren Ehrgeiz.", sourceObjectiveStatus = "unverified-source-field" }
quests[81687] = { id = 81687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein farbenprächtiger Tod", description = "Ich dachte, sie gegeneinander auszuspielen, würde mir Schutz bieten. Doch all das hat nur Rak-Ahat ins Chaos gestürzt! Das könnte unsere ganze Operation gefährden!\n\nIhr habt gehört, was Antourix gesagt hat. Sie hat die Farbbäder bereits mit all den Reagenzien aufgestockt, die Ihr gesammelt habt. Ich weiß nicht, was sie bewirken, aber wenn sie vorhat, sie gegen Ren'khat einzusetzen... habt Ihr jeden Grund, sie zur Beseitigung der beiden Schläger zu gebrauchen.\n\nProbiert diese Farbbäder aus und säubert die Färberei!", sourceObjective = "Tötet 8 Färbereineruber mithilfe der Kraft, die Euch die augmentierten Farbbäder verliehen haben.", progress = "Ich wollte nur weniger Gezanke, das meiner Arbeit in die Quere kommt, mehr nicht!", completion = "Teile der Ausrüstung sind kaputt und Teile der Arbeiter verängstigt... aber am wichtigsten ist, dass alle ihre Lakaien aus dem Weg sind. Ich betrachtet das als Sieg.", sourceObjectiveStatus = "unverified-source-field" }
quests[81688] = { id = 81688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das war es schon", description = "Es wird interessant, mit anzusehen, wie sich das alles entwickelt… aber wie ich die Weberin kenne, wird sie mit Sicherheit ein paar Fäden ziehen, um die Ereignisse ihren Wünschen entsprechend zu lenken.\n\nDas ist das Geheimnis, über das ich sie unterrichten wollte, als die Lage sich allmählich zuspitzte. Warum überbringt Ihr es ihr nicht? Als Zeichen gut geleisteter Arbeit.\n\nSie wird sich bestimmt freuen, wenn sie erfährt, dass sie in Rak-Ahat immer noch ein Paar Augen hat.", sourceObjective = "Bringt Seide mit geheimer Nachricht ins Nest der Weberin.\n\nBereitgestellter Gegenstand:", completion = "Aha, ich gebe zu, damit hatte ich nicht gerechnet.\n\n<Die Weberin fährt mit ihren Pedipalpen über die geheimnisdurchwebte Seide und freut sich.>\n\nSehr interessant. Das werde ich im Hinterkopf behalten müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81689] = { id = 81689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrichtung: Gundargaz", description = "Unsere neuen Koboldfreunde wandern nach Gundargaz ein. Außerdem klauben sie alles Mögliche aus den Schallenden Tiefen zusammen.\n\nSucht doch mal den Rüstmeister auf und seht Euch an, was sie gesammelt haben. Danach können wir unsere nächsten Schritte besprechen.\n\nAngeblich soll sich Anduin irgendwo hier aufhalten. Er hat sicher einen Plan für Heilsturz. Wir brauchen jeden Verbündeten gegen die Neruber.", sourceObjective = "Trefft Euch mit Wachshändler Squick in Gundargaz.", progress = "Neue Verbündete sind immer gern gesehen.", completion = "Es ist wichtig, neue Freundschaften zu knüpfen. In den Tagen, die vor uns liegen, werden wir jede Hilfe brauchen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[81690] = { id = 81690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht am Ende des Tunnels", description = "Ich habe noch nie so finstere Schatten gesehen. So... bösartig.\n\nEs fühlt sich fast so an, als würden sie nach uns greifen.\n\n<Faerin schüttelt sich.>\n\nWir können nicht hierbleiben.", sourceObjective = "Entkommt mit Faerin und Anduin aus der Düsterfelsenlaube.", completion = "Ich bin froh, dass Ihr in Sicherheit seid. Ich spürte, dass etwas nicht stimmte, als diese Wesen plötzlich aufhörten, den Turm anzugreifen, und verschwanden. Kurz darauf verschob Beledar sich von allein.\n\nDas war keine einfache Illusion, in der Xal'atath Euch gefangen hatte. Ich frage mich, ob ich eigentlich das Ziel war?\n\nIhr, ich, Anduin, Faerin... Vielleicht reichte es ihr schon, einen von uns gefangen zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[81691] = { id = 81691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Schatten der Tiefe" }
quests[81692] = { id = 81692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flamme im Inneren", description = "Wenn ein Zunderkasten entzündet wird, erzeugt er eine Flamme, die die Essenz der Lebensreise seines Trägers verkörpert. Sie ist ein Spiegelbild Eures Geistes und Eurer inneren Stärke.\n\nAuf Euren Reisen seid Ihr vielen begegnet, die uns bei der Herstellung eines Zunderkastens helfen können, der eine Flamme für Euren überragenden Geist entfachen könnte.\n\nBittet Sprecher Kuldas in Gundargaz um Hilfe. Das Wissen des Irdenen wird Euch dabei helfen, einen mächtigeren Zunderkasten zu bauen.", sourceObjective = "Sucht Sprecher Kuldas in Gundargaz auf und sichert Euch seine Hilfe.", completion = "Es war richtig, dass Ihr mich um meine Unterstützung ersucht habt. Es gibt nur wenige Probleme, die ein Maschinenflüsterer wie ich nicht lösen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[81693] = { id = 81693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skorthuz verzweifelt gesucht", description = "Hm? Wer seid Ihr denn? Ach, stimmt, ich habe gehört, dass wir neue Gesichter unter uns haben.\n\nSagt mal, seid Ihr zufällig auf dem Weg in den Norden? Könntet Ihr in dem Fall nach meinem Freund Skorthuz Ausschau halten? Der Trödelhans sollte vor einer Stunde schon zurück sein, aber keine Spur von ihm. Wie ich hörte, hat er sich aus irgendeinem schlimmen Grund auf den Weg zum Zirpenden Bau gemacht.\n\nWenn Ihr ihn seht, sagt ihm, dass er sich gefälligst beeilen und zurückkommen soll, sonst trinke ich ohne ihn!", sourceObjective = "Sucht in der Nähe des Zirpenden Baus nach Skorthuz.", completion = "Wer seid Ihr denn? Oh, Hrandaz schickt Euch? Ist es schon so spät?", sourceObjectiveStatus = "unverified-source-field" }
quests[81696] = { id = 81696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch im Handelsposten (D)", description = "Questbeschreibung", sourceObjective = "Kehrt zum Handelsposten zurück und nehmt Eure Händlerdevisen aus der Truhe des Sammlers.", sourceObjectiveStatus = "unverified-source-field" }
quests[81710] = { id = 81710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Met für den Katalog" }
quests[81712] = { id = 81712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lisk-ante Angelegenheit", description = "Hrandaz muss sich noch gedulden. Meine geliebte Lisky ist verschwunden! Sie ist in die Höhle gelaufen und nicht mehr rausgekommen. Vermutlich hat sie angezogen, was immer diesen furchtbaren Gestank verursacht.\n\nBitte geht hinein und findet meine Lisky. Noch sind die schrecklichen Kreaturen in der Höhle nicht auf sie aufmerksam geworden, aber es ist nur eine Frage der Zeit!", sourceObjective = "Rettet Lisky aus der Höhle.", progress = "Meine liebste, kostbarste Lisky! Bitte holt sie da raus.", completion = "Ihr habt sie gefunden! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[81713] = { id = 81713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleimodius", description = "Ich habe selbst versucht, Lisky zurückzuholen, aber sie ist ans andere Ende der Höhle gerannt. Das ganze Ding ist voller ekelhafter Würmer.\n\nAls ob die nicht schon schlimm genug wären, ist da hinten auch noch eine Kreatur, die so eklig und schleimig ist, dass ich um mein Leben gerannt bin!\n\nNein, ich bin nicht stolz darauf, Lisky zurückgelassen zu haben. Ich wollte gerade den Mut aufbringen, wieder hineinzugehen, als Ihr gekommen seid. Bei Eurer Suche nach Lisky solltet Ihr diese ekligen Dinger da drinnen entsorgen! Ich bin mir ziemlich sicher, dass sie sich vermehren!", sourceObjective = "Tötet 6 Schleime und Schleimodius.", progress = "Ich zähle auf Euch, die Drecksarbeit zu erledigen. Wenn ich ehrlich bin, habe ich eine irrationale Angst vor Würmen und anderem klebrigen Getier.\n\nTrockene, feste, steinige Kreaturen mag ich viel lieber. Vor allem, wenn sie schön harte Schuppen haben!", completion = "Ihr habt es geschafft! Mir ist unerklärlich, wie Ihr nicht von oben bis unten vollgeschleimt seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[81714] = { id = 81714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch im Handelsposten", sourceObjective = "Wir hoffen, Euch gefällt die monatliche Sammlung neuer und exotischer Waren, {name}.", sourceObjectiveStatus = "unverified-source-field" }
