quests[81748] = { id = 81748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft dem Sonnenhäscheransturm", progress = "Meine Späher berichten von Feindaktivität. Habt Ihr Vorräte für unsere Truppen dabei?", completion = "Sehr gut. Wir werden sofort den Gegenangriff vorbereiten." }
quests[81749] = { id = 81749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft der Offensive der Kirin Tor", progress = "Ohne Blutvergießen kann es keinen Sieg geben. Seid Ihr hier, um uns zu helfen, {class}?", completion = "Das wird der Kriegskasse zugutekommen." }
quests[81750] = { id = 81750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolkenernten" }
quests[81751] = { id = 81751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer und Edelstein", description = "Was ist das? Ein Zunderkasten?\n\nIch habe Erzählungen von diesen Geräten der Arathi gehört, aber ich hatte nie einen in der Hand. Er ist kleiner, als ich gedacht hätte...\n\nAufwerten, sagt Ihr? Pah! Das kriegen wir hin. Wenn wir die Maschine das nächste Mal erwecken, haltet Ausschau nach einem erweckten Zahnrad und einem klingelnden Edelstein.", sourceObjective = "Beschafft ein erwecktes Zahnrad und einen klingelnden Edelstein von der Erweckung der Maschine.", progress = "Habt Ihr die Sachen für mich?", completion = "Ihr habt sie! Dem Zahnrad sei Dank und das Getriebe sei gesegnet. Mal sehen, was wir mit Eurem magischen kleinen Ding anfangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[81767] = { id = 81767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnorrt den Schrott!" }
quests[81793] = { id = 81793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Krieges: Insel von Dorn", description = "Mächtige Kreaturen treiben auf der Insel von Dorn ihr Unwesen. \n\nZieht los und räumt auf!", sourceObjective = "Sammelt bei aktivem Kriegsmodus 100 Funken des Krieges auf der Insel von Dorn.", progress = "Am besten direkt anfangen.", completion = "Endlich kann unsere Wacht ungestört fortgesetzt werden. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[81794] = { id = 81794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Krieges: Die Schallenden Tiefen", description = "Unsichtbare Kräfte haben mehrere irdene Außenposten überrannt. \n\nMacht sie ausfindig und säubert die Tiefen.", sourceObjective = "Sammelt bei aktivem Kriegsmodus 100 Funken des Krieges in den Schallenden Tiefen.", progress = "Wie läuft die Rückgewinnung?", completion = "Ihr habt die tiefe Quelle überlebt!", sourceObjectiveStatus = "unverified-source-field" }
quests[81795] = { id = 81795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Krieges: Heilsturz", description = "Das Licht ist unstet, aber es wird Euch vor der Dunkelheit retten, wenn Ihr es meistert.\n\nGeht. Reist nach Heilsturz und teilt Eure Stärke mit den Arathi.", sourceObjective = "Sammelt bei aktivem Kriegsmodus 100 Funken des Krieges in Heilsturz.", progress = "Hütet Euch vor der Dunkelheit.", completion = "Dank Euch haben die Arathi jetzt einen Moment Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[81796] = { id = 81796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Krieges: Azj-Kahet", description = "Wir haben seltsame Messwerte aus Azj-Kahet erhalten. Untersucht diese Orte, aber bleibt wachsam.", sourceObjective = "Sammelt bei aktivem Kriegsmodus 100 Funken des Krieges in Azj-Kahet.", progress = "Geht und schließt Eure Untersuchung ab.", completion = "IHR HABT ÜBERLEBT? Und obendrauf mit unversehrten Gliedmaßen. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[81797] = { id = 81797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gezielte Aufklärung", description = "Wenn Ihr Zeit in Heilsturz verbracht habt, so habt Ihr zweifellos Erfahrungen mit der verderbten Magie der Kobyss gemacht. Berichte, dass ihre Illusionen sich weiterentwickelt haben, werden innerhalb der Arathiarmee heiß diskutiert.\n\nEure Perspektive von außen ist genau das, wonach ich suche. Begebt Euch zum Sonnenlosen Strand, ringt ein paar ihrer illusorischen Meuchelmörder nieder und erstattet über Eure Funde Bericht. Ihr werdet sie vermutlich in den Schatten finden, in denen sie sich verstecken.", sourceObjective = "Erschlagt drei Schemenformer der Kobyss am Sonnenlosen Strand.", completion = "Ihre illusorischen Projektionen von arathischen Bürgern klingen so überzeugend wie immer. Es fällt mir schwer, zu glauben, dass solche bösartigen und undiplomatischen Wesen die Eigenheiten der Arathi so gut nachbilden können.\n\nNichtsdestotrotz entspricht all dies unseren Eindrücken über die Kobyss. Euer Bericht wird gut genutzt werden. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[81798] = { id = 81798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Moira zurück.", description = "Sprecherin Brinthes Impulsivität hat sie mal wieder im Griff.\n\nKehrt am besten zu Euren Kameraden zurück und informiert sie über ihre Pläne!", sourceObjective = "Kehrt zu Moira im Erdwerk zurück.", completion = "{name}! Ihr seid zurück. Lasst uns dieses Schmierentheater beenden.", sourceObjectiveStatus = "unverified-source-field" }
