quests[81862] = { id = 81862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katzenchaos" }
quests[81869] = { id = 81869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Honig ist gut Feuer fangen", description = "Die Fertigung mit der Flamme erfordert einen Brennstoff, der rein, nachhaltig und kraftvoll brennt. Der Honig, den die Aschenholtzbienen produzieren, sticht dabei besonders hervor! Er ist eine Quelle des elementaren Feuers, organisch und unverfälscht.\n\nIch wünsche mir schon lange einen Vorrat dieses Honigs, hatte aber nie eine Gelegenheit, ihn zu beschaffen.\n\nNehmt mein Erntegerät und sammelt eine Menge für unseren Zweck. Wir werden ihn in Euren Zunderkasten füllen. Seid auf der Hut, denn manche Irdene verehren diese Bienen als heilige Wesen!", sourceObjective = "Beschafft 10 reinen Feuerhonig von den überladenen Drohnen in Aschenholtz.", progress = "Habt Ihr den Honig beschafft?", completion = "So süß, und die Flamme entspringt sogar jetzt schon. Das ist ein hervorragender Brennstoff für Euren Zunderkasten!", sourceObjectiveStatus = "unverified-source-field" }
quests[81886] = { id = 81886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Allianz", description = "Zum ersten Mal in unserer Geschichte steht es uns frei, die Außenwelt zu erkunden und zu erleben.\n\nEine fremde Fraktion namens Allianz kam unseren Leuten zu Hilfe. Die standhafte Allianz, tapfer und weise, hat unserem Volk die Hand gereicht.\n\nWerdet Ihr zu den Ersten gehören, die diese neuen Länder besuchen, ihre Geschichte lernen und sich unter ihren Leuten aufhalten?\n\nWenn Euch dieser Weg ruft, dann hoffe ich, dass Ihr zurückkommt, um diese Erfahrungen zu teilen und den Irdenen zu zeigen, was die Welt zu bieten hat.", sourceObjective = "Trefft Euch mit Botschafter Moorgard in der Botschaft von Sturmwind.", completion = "Nun, da wären wir! Noch einer der Irdenen aus... Khaz Algar, richtig?\n\nEinige Wildhämmer haben verlautbart, dass Repräsentanten Eures Volks uns möglicherweise bald einen Besuch abstatten.\n\nAlso dann, fühlt Euch in unserer Stadt wie zu Hause. Die Allianz heißt alle neuen Freunde mit offenen Armen willkommen.\n\nWillkommen in Sturmwind!", sourceObjectiveStatus = "unverified-source-field" }
quests[81887] = { id = 81887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einem fremden Land", description = "Willkommen in Sturmwind, {race}. Ich lade Euch ein, unsere prächtige Stadt zu erkunden. Hm, Ihr seht aus wie jemand, der feine Steinarbeiten zu schätzen weiß! In Sturmwind gibt es viele beeindruckende Gebäude und Mauern aus Stein.\n\nAber das kann warten. Ein Bronzedrache möchte Euch sprechen. Sie sitzt unter dem Baum in der Nähe, ausgerechnet auf einem Stundenglas!\n\nUnd danach erwartet Euch einer Eurer Abgesandten, der Euch in der Stadt willkommen heißen will. Klingt, als hättet Ihr einen langen Tag vor Euch!\n\nIch wünsche einen angenehmen Aufenthalt, {name}!", sourceObjective = "Sprecht mit Chromie in Sturmwind", progress = "Seid gegrüßt, {name}.", completion = "Willkommen in Sturmwind. Gewöhnt Euch ein und lernt, so viel Ihr könnt.\n\nUnsere Erfahrungen werden für die Archive in Dornogal von unschätzbarem Wert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[81888] = { id = 81888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Horde", description = "Zum ersten Mal in unserer Geschichte steht es uns frei, die Außenwelt zu erkunden und zu erleben.\n\nEine fremde Fraktion namens Horde kam unseren Leuten zu Hilfe. Die ehrenwerte Horde, spirituell und mächtig, hat unserem Volk die Hand gereicht.\n\nWerdet Ihr zu den Ersten gehören, die dorthin gehen, wo noch kein Irdener je gewesen ist? Um ein neues Land zu betreten, neue Lieder zu hören und von einem unbekannten Volk zu lernen?\n\nWenn Euch dieser Weg ruft, dann hoffe ich, dass Ihr zurückkommt, um diese Erfahrungen zu teilen und den Irdenen zu zeigen, was die Welt zu bieten hat.", sourceObjective = "Trefft Euch mit Botschafter Schwarzwacht in der Botschaft von Orgrimmar.", completion = "Was ist das denn? Ein... {race}? Ich hatte gehört, dass wir hier ein paar von Eurer Art treffen könnten.\n\nNun denn, macht es Euch gemütlich, wenn Ihr könnt.\n\nWir haben jede Menge Steine an diesem brütend heißen Ort. Falls das Euer Ding ist, werdet Ihr also gut zurechtkommen.\n\nNur... esst die Steine nicht. Esst Ihr überhaupt Steine?\n\nWie auch immer, willkommen in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[81889] = { id = 81889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einem fremden Land", description = "Hallo, ich bin Botschafter Schwarzwacht.\n\nEs ist mir eine Ehre, Euch in Orgrimmar willkommen zu heißen, {race}.\n\n<Er lächelt gekünstelt.>\n\nNun, da sich ein Leben voller Abenteuer vor Euch auftut, seid versichert, dass... ähm...\n\nWisst Ihr was? Ich habe diese Begrüßung heute den ganzen Tag immer wieder abgespult. Mir reicht's.\n\nSprecht mit Chromie auf dem Stundenglas. Und dann sprecht mit Eurem Abgesandten. Kusch!", sourceObjective = "Sprecht mit Chromie.", progress = "Seid gegrüßt, {name}.", completion = "Willkommen in Orgrimmar. Gewöhnt Euch ein und lernt, so viel Ihr könnt.\n\nUnsere Erfahrungen werden für die Archive in Dornogal von unschätzbarem Wert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[81890] = { id = 81890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerledigte Anfragen", description = "Ich habe gehört, dass die Bürger des Seidendistrikts Probleme mit einer Gruppe Aufgestiegener haben, die sich die Blassen Webpeitscher nennen.\n\nDer neue Distrikt soll ein Neubeginn für die Bürger der Hauptstadt sein - zumindest erzählt die Königin es so. In Wirklichkeit ist es eine Möglichkeit für sie, jene besser zu kontrollieren, denen sie misstraut.\n\nTrefft Euch mit meiner Assistentin Sum'latha. Ich habe sie vorausgeschickt, um Informationen zu sammeln. Sie kann Euch über alle Details aufklären.", sourceObjective = "Trefft Euch mit Sum'latha im Seidendistrikt.", completion = "Ihr müsst die Hilfe sein, die der Wesir entsendet hat. Willkommen im Seidendistrikt.", sourceObjectiveStatus = "unverified-source-field" }
quests[81896] = { id = 81896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu und jetzt noch besser", description = "Ich habe die Modifikationen abgeschlossen. Ich muss sagen, ich habe mich mal wieder selbst übertroffen!\n\nSo bescheiden es auch aussehen mag - mit ein bisschen Getriebeöl und Ellenbogenschmalz habe ich es in ein Gerät verwandelt, das selbst die verdrießlichsten Flammenanbeter zu schätzen wüssten.\n\nWenn einer von ihnen wissen will, wie sie es nachmachen können, schickt sie nur zu mir.", sourceObjective = "Nehmt den neuen und verbesserten Zunderkasten von Kuldas entgegen.", completion = "Das Feuer des Zunderkastens wird heller brennen als je zuvor!", sourceObjectiveStatus = "unverified-source-field" }
quests[81906] = { id = 81906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüstern aus dem Netz", description = "Hey! Hey!\n\n<Das Mädchen wedelt mit den Armen, um Eure Aufmerksamkeit zu erregen, und umklammert mit der Hand einen Zettel.>\n\nIhr werdet es nicht glauben, aber ich habe den süßesten, flauschigsten Welpen gefunden! Mit einem Glöckchen! Um den Hals!\n\nEr gab mir das hier für Euch. Nehmt es, ich muss den Welpen fangen!\n\n<Das Schreiben ist in eleganter Handschrift verfasst und beordert Euch nach Azj-Kahet.>", sourceObjective = "Trefft Euch mit Ct'nak im Bau von Azj-Kahet.", completion = "Meine Nachricht hat Euch also erreicht. Ihr seid... nicht so imposant, wie ich es mir vorgestellt hatte, aber angeblich sind Eure Fertigkeiten unübertroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81908] = { id = 81908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Flamme im Dunkeln", description = "In der Tiefenfestung liegt ein Zunderkasten, der einst dem verstorbenen Aelric Leid gehörte.\n\nDieser Gegenstand stinkt förmlich nach einer mächtigen, verderblichen Energie. Seine Nähe hat auf viele Neruber abgefärbt.\n\nEure Aufgabe ist es, den Kasten zurückzuholen und mir zu bringen. Sammelt am besten alle Zunderkästen, die Ihr findet... Wir werden sie alle zerstören, nur um sicherzugehen.", sourceObjective = "Sucht in verschiedenen Behältern in der Tiefenfestung nach 8 unidentifizierten Zunderkästen und Aelrics verderbtem Zunderkasten.", progress = "Habt Ihr die Zunderkästen gefunden?", completion = "Gebt ihn mir schnell... er darf nicht in der Öffentlichkeit gesehen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[81909] = { id = 81909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absolute Macht", description = "Die dunkle Verlockung, die von diesem Gegenstand ausgeht, übertrifft meine ursprünglichen Erwartungen. Ich spüre eine Welle der Macht, die mich durchströmt.\n\nWir müssen seine Geheimnisse genauer erforschen.\n\nWie auch immer, es ist unklug, diese Angelegenheit offen zu diskutieren. Folgt mir nach drinnen, wo wir die Sache weiter besprechen können.", sourceObjective = "Besprecht die Zerstörung des Zunderkastens mit Ct'nak.", progress = "Was habt Ihr da?", completion = "Das ist höchst unerwartet. Wo um alles in der Welt habt Ihr das gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[81910] = { id = 81910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine große Verantwortung", description = "Solch eine Verderbnis zu sehen, ist zutiefst beunruhigend.\n\nTrotz der dunklen Energien, die mit diesem Zunderkasten verwoben sind, gibt es noch ein Fünkchen der Heiligen Flamme, das zu entkommen versucht. Ich werde dieses Fünkchen nicht zerstören.\n\nAber ich wage es nicht, es länger festzuhalten.\n\nVielleicht kann Euer reiner Geist der Dunkelheit in seinem Inneren wiederstehen. Bitte, {name}, nehmt es. Schützt den kleinen Funken der Reinheit und helft ihm, sich von der dunklen Magie, die ihn umgarnt, zu befreien.", sourceObjective = "Nehmt den Zunderkasten an.", completion = "Ich lege diesen kleinen Funken der Hoffnung in Eure Obhut, verbunden mit der schweren Verantwortung, ihn zu bewahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[81912] = { id = 81912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugausbildung für Fortgeschrittene", description = "Glaubt ja nicht, ich hätte nicht bemerkt, dass diese Krähen Blitze spucken. Das ist fraglos besser, als Hämmer zu werfen, aber es bringt nichts, wenn die Sturmreiter ihre Ziele nicht treffen.\n\nStellen wir sie auf die Probe! Ich habe hier ein paar gnomische Gerätschaften, die Übungsziele für uns projizieren können. Nehmt Shraubendre mit raus und zeigt, wie man es macht!", sourceObjective = "Helft Kurdran bei der Ausbildung von Rekruten in der Luftzielbekämpfung.", progress = "Zum Fliegen braucht man eine feste Hand. Und Junge, die haben diese Irdenen!", completion = "So geht das! Ihr habt es diesen Projektoren ordentlich gezeigt. Aber jetzt brauchen wir ein bewegliches Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[81913] = { id = 81913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugausbildung für Experten", description = "Diese Rekruten scheinen einer Herausforderung gewachsen zu sein. Besorgen wir ihnen etwas mit ein wenig Biss!\n\nGleich an der Küste habe ich einen armen Riesen gesehen, der von einem Schwarm dieser fliegenden Teufel belästigt wurde. Mal sehen, ob diese Krähen ihnen die Flügel abschießen und dem Kerl etwas Erleichterung verschaffen können.\n\nIhr und Shraubendre seid ein gutes Beispiel für den Rest. Macht weiter so!", sourceObjective = "Helft Kurdran bei der Ausbildung von Rekruten im Luftkampf.", completion = "Die Ausbildung ist gut gelaufen, ja? Tut mir leid, dass ich nicht vor Ort war. Ich hatte etwas zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81914] = { id = 81914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dhar Oztan", description = "Ich liebe die Sturmkrähen. Für sie zu sorgen ist meine Direktive, sie sind alles, was ich kenne. Aber dennoch gibt es Fragen zu ihnen, auf die ich keine Antwort weiß.\n\nBaelgrim – Sturmwehr Baelgrim – war der Experte. Ich habe ihn zu jeder Gelegenheit ausgefragt. Und er teilte mit mir, was er wusste.\n\nEr hat mir einst erzählt, wie man Krähen in Dhar Oztan beschwört. Das ist ein alter Außenposten der Sturmreiter, noch älter als der Sturmhort. Wenn Ihr mehr über Sturmkrähen erfahren wollt, sollten wir da hingehen.", sourceObjective = "Reist nach Dhar Oztan.", completion = "Baelgrim ist also fort. Und andere sind gekommen. Ihr habt vor, noch mehr Krähen zu beschwören, oder nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[81915] = { id = 81915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heim zum Horst", description = "Ihr habt uns bereits einen großen Dienst erwiesen, {name}. Wir werden uns an Eurem Beispiel orientieren.\n\nIhr solltet nach Dhar Oztan zurückkehren und Euch um die neuen Sturmreiter kümmern, die Ihr rekrutiert habt. Sie werden zweifelsohne von der gleichen Sorgfalt profitieren, die Ihr hier an den Tag gelegt habt.\n\nUnd Ihr kommt von diesen beiden und ihrem Gehabe weg. Ich beneide Euch, {name}...", sourceObjective = "Kehrt nach Dhar Oztan zurück.", completion = "Gut, dass Ihr wieder da seid. Ist mit den Bodentruppen alles gut gelaufen?\n\nWir wollen hier jetzt mit der Flugausbildung beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81928] = { id = 81928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stimme des Volkes", description = "Wie Ihr vielleicht schon gehört habt, sind die Dinge für die Bürger des Seidendistrikts nicht so gelaufen, wie sie es sich vorgestellt hatten. Die Blassen Webpeitscher haben die Bürger fest im Griff. \n\nIch konnte nicht viel herausfinden, bevor mich ein Aufgestiegener wegen Herumschnüffelns rausgeschmissen hat. Ihr seid ein unbekanntes Gesicht - spaziert im Seidendistrikt umher und sprecht mit den Bürgern. Vielleicht findet Ihr einen Weg, ihnen zu helfen.\n\nSucht auch Alchemist Talbax auf. Sein Name ist ein paar Mal gefallen. Er könnte ein nützlicher Kontakt sein.", sourceObjective = "Sprecht mit 3 Bewohnern des Seidendistrikts.", progress = "Der Seidendistrikt sollte für diese Leute ein Ort des Neuanfangs sein. Mal sehen, was wir tun können, um zu helfen.", completion = "Ah, Ihr habt also von meinen Sorgen gehört, mein Freund. Ihr könntet mir helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81929] = { id = 81929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So wird das ablaufen", description = "{name}, die Zeit ist gekommen, uns der nerubischen Armee zu stellen. General Zev'kall mobilisiert eine gewaltige Streitmacht im Osten. Er will die Mauer durchbrechen und in Heilsturz einfallen. Wir haben nicht viel Zeit.\n\nWir haben nicht die Kraft für einen Großangriff. Deshalb hat die Weberin Gazlowe zur Unterstützung hergeschickt. Ich bin zu allem bereit, um mein Volk zu retten.\n\nUnd wie es das Schicksal so will, habe ich eine persönliche Angelegenheit zu erledigen, während wir dort sind.", sourceObjective = "Helft Faerin mit den Vorbereitungen, während sie ihren Plan erläutert.", progress = "Ich lerne gerade, dass nicht alle Neruber schlecht oder gleich sind. Ich hoffe nur, dass wir drei ausreichen.", completion = "Wir drei sollten hierfür reichen. Klein aber oho, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[81930] = { id = 81930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Krieg im Inneren", description = "Überall in Azeroth erleben Leute Visionen des \"strahlenden Gesangs\". Wir haben Grund zu der Annahme, dass das eine Art Warnung sein soll.\n\nTrefft mich in Silithus. Vielleicht hat Azeroths Sprecher eine Erklärung dafür, was diese Warnung bedeuten mag.", sourceObjective = "Geht nach Silithus und sprecht mit Jaina über die Visionen, die sich über Azeroth verbreiten.", completion = "Es sind alle da. Gut. Finden wir heraus, was der strahlende Gesang uns zu sagen versucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[81945] = { id = 81945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Arathis Ende", description = "Wir werden uns in den Außenbezirken von Arathis Ende im Osten neu aufstellen.\n\nIhre Streitkräfte sind fast bereit und es bleibt nicht viel Zeit, {name}.", sourceObjective = "Stellt Euch mit Faerin und Gazlowe in Arathis Ende neu auf.", completion = "Ihr habt es geschafft. Schauen wir mal, ob wir die Neruber dezimieren und Heilsturz retten können.\n\nIch kann die Belohnungen schon schmecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[81950] = { id = 81950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Leckereien!", description = "Wenn wir diese Invasion stoppen wollen, müssen wir die schweren Geschütze ausschalten, die sie aufgefahren haben. In diesem Fall steht die Metapher für Ballisten.\n\nErinnert Ihr Euch, wie ich Euch aufgetragen habe, Käfersnacks zu besorgen? Das habe ich nicht ohne Grund getan. Die Neruber lassen ihre Bomben von Käfern transportieren. Und diese Käfer lieben Snacks. Ich meine, wer nicht?\n\nPlatziert die Snacks neben einer Balliste. Dann läuft ein Bombenkäfer darauf zu und BUMM!", sourceObjective = "Platziert Käfersnacks, um sprengstoffgeladene Käfer dazu zu bringen, die Ballisten der Neruber zu zerstören.", progress = "Diese Ballisten zerstören sich nicht von selbst, kapiert?!", completion = "Ich hätte es selbst nicht besser machen können. Na ja, vielleicht schon. Wenn ich so drüber nachdenke, sehr wahrscheinlich sogar.\n\nSo oder so, Arbeit erledigt. Und sogar zum kleinen, kleinen Preis einer aufgedunsenen Tasche mit verarbeitetem Schrott, in der sich weiß Gott was befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[81959] = { id = 81959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt ein Gemisch", description = "Die blassen Webpeitscher haben doch tatsächlich meine alchemistischen Vorräte die Klippen hinuntergeworfen. Diese Tränke werden den Bürgern im Seidendistrikt den Vorteil bringen, den sie für ihren Aufstand brauchen.\n\nIch brauche jemanden, der die Flüsternden Klippen hinabsteigt und alle Flaschen aufsammelt, die nicht zerbrochen sind. Ich würde selbst gehen, aber die Kobyss haben diesen Bereich zu einem Jagdgebiet erklärt und ich bin kein Kämpfer.\n\nDas wäre doch eine recht simple Aufgabe für jemanden wie Euch, oder?", sourceObjective = "Sammelt 8 Tagschattentränke in den Flüsternden Klippen.", progress = "Die Kobyss sind mehr als lästig. Ich muss meine Lichtschatten-Tränke wiederbekommen.", completion = "Ich hoffe, Ihr habt meine Tagschatten-Tränke? Ohne sie habe ich gar nichts mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[81962] = { id = 81962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schubser in die richtige Richtung", description = "Wunderbar, wunderbar! Jetzt, wo wir meine Tagschattentränke wiedergefunden haben, möchte ich, dass Ihr damit im Seidendistrikt prahlt!\n\nDas wird den Zorn der blassen Webpeitscher auf sich ziehen, da bin ich mir sicher, aber ich möchte der Bevölkerung zeigen, dass wir nicht unter ihrer Fuchtel leben müssen. Mit ein wenig aggressiver Motivation können wir uns behaupten.\n\nJa, ja, das wird funktionieren! Geht in den Seidendistrikt und tötet blasse Webpeitscher. Meine Tränke sorgen für einen zusätzlichen Kick, den die Bürger mit Sicherheit lieben werden.", sourceObjective = "Tötet 10 Blasse Webpeitscher im Seidendistrikt.", progress = "Achtet auf jegliche Nebeneffekte, die durch die Tränke auftreten könnten, damit ich sie festhalten kann.", completion = "Die Tränke wirken Wunder, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[81963] = { id = 81963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Früchte unserer Arbeit", description = "Ihr habt eine tolle Vorstellung hingelegt, ja? Die Bestellungen gehen bereits ein. Die Bürger können es kaum erwarten, die Tränke in die Mandibeln zu bekommen.\n\nIch habe noch eine letzte Aufgabe für Euch. Ich möchte, dass Ihr diese letzten Bestellungen ausliefert. Das macht Ihr, ja?\n\nDie Bürger rühren sich. Jetzt müssen wir den blassen Webpeitschern zeigen, wozu wir fähig sind. Wenn jemand Euch aufhalten will, wisst Ihr, was zu tun ist.", sourceObjective = "Liefert 3 Tagschattentränke an die Bürger im Seidendistrikt.", progress = "Die Zeit ist gekommen. Die Blassen Webpeitscher sind nicht unbesiegbar.", completion = "Das habt Ihr gut gemacht. Die Bürger haben alles, was sie brauchen, um die blassen Webpeitscher zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81964] = { id = 81964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal des Schmieds", description = "Wo wir schon da sind, ich muss herausfinden, was mit meinem alten Freund, Ryton Schwarzholm, passiert ist. Er war der beste Schmied von Heilsturz... aber er wurde von einem Angriff der Neruber überrascht. Ich konnte ihn nicht retten.\n\nIch habe überall nach ihm gesucht, aber nichts außer seinem blutbeschmierten Helm gefunden. Ich hatte die Hoffnung schon aufgegeben, aber vor Kurzem habe ich ein Gerücht gehört. Ein Überlebender, der von der Aegismauer gezogen wurde, hat von einem Schmied berichtet.\n\nKönnte das Ryton sein? Helft Ihr mir, {name}?", sourceObjective = "Helft Faerin Lothar dabei, das Schicksal von Ryton Schwarzholm aufzudecken.", progress = "Danke für Eure Hilfe, {name}.", completion = "Ich kann es einfach nicht fassen, dass Ryton wirklich tot ist, aber es bedeutet mir alles, dass ich endlich weiß, was meinem guten Freund zugestoßen ist.\n\nWir werden ihn ehren, sobald wird uns um Zev'kalls Monstrosität gekümmert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[81965] = { id = 81965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Störung der Invasion", description = "Auch wenn wir die nerubische Bedrohung hier nicht ausmerzen können, können wir doch ihre Invasionspläne zerrütten.\n\nEs gibt viele verschiedene Wege, unser Ziel zu erreichen. Schauen wir mal, welchen Schaden wir anrichten können.", sourceObjective = "Zerrüttet die nerubischen Invasionsbemühungen am Ende der Arathi.", progress = "Je mehr wir hier erreichen, umso sicherer werden die Dinge für Heilsturz.", completion = "Das sollte vorerst reichen. Wir müssen immer wieder zurückkommen, um ihre Streitkräfte zu schwächen, bis sich uns eine andere Lösung bietet.", sourceObjectiveStatus = "unverified-source-field" }
quests[81966] = { id = 81966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschlafen wie ein Stein", description = "Champion, Ihr seid wach. Bitte kehrt nach Dalaran zurück.", sourceObjective = "Kehrt nach Dalaran zurück.", completion = "Willkommen zurück, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[81969] = { id = 81969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Endes", description = "Ich will meinen Freund ehren, aber zuerst müssen wir diesem vom Licht verlassenen Ort den Todesstoß versetzen.\n\nEs ist allgemein bekannt, dass General Zev'kall die Erschaffung einer Monstrosität überwacht hat... eines leerenverderbten, missgebildeten Nerubers. Dem Späherbericht zufolge hält er sich oben am Rand der Schlucht auf.\n\nWir werden ihm dieses schreckliche Haustier entreißen. Das sollte seinen Plänen, in Heilsturz einzufallen, ein Ende setzen. Wenigstens für kurze Zeit.", sourceObjective = "Arbeitet mit Faerin und Gazlowe zusammen, um die als Surek'tak der Entzweite bekannte Monstrosität zu erledigen.", completion = "Habt Dank, {name}. Die Einwohner von Heilsturz stehen in Eurer Schuld.\n\nIch habe da noch eine Sache, um die ich Euch gerne bitten würde, wenn Ihr erlaubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[81976] = { id = 81976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basar, nicht wahr?", sourceObjective = "Habt Ihr Bronze? Gebt sie auf dem Basar aus!\n\nDies bringt Euch dorthin. Das erste Mal ist gratis!", sourceObjectiveStatus = "unverified-source-field" }
quests[81981] = { id = 81981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welche Armee?" }
quests[81985] = { id = 81985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseelenerinnerung: Die Weltenschnitzer" }
quests[81990] = { id = 81990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Lichts", description = "Hergehört, Bürger von Heilsturz!\n\nEs wird dringend Unterstützung benötigt, um die Außenbezirke in den Schatten zurückzuerobern.\n\nDa unzählige Höfe von Familien der Finsternis zum Opfer gefallen sind, bedarf es Eurer Hilfe, die Heilige Flamme zu entzünden und unseren Ländern Sicherheit zurückzubringen.", sourceObjective = "Meldet Euch bei Keyrra Flammenzunge für weitere Aufgaben.", completion = "Wir sind froh, dass Ihr uns unterstützen wollt. Alles, was Ihr tun könnt, um diese Schlüsselflammen erneut zu entzünden, wird helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[81993] = { id = 81993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmreiterbande", description = "Bei dieser Schönheit handelt es sich um keinen gewöhnlichen Greif. Er hat den Sturm in sich. Ich versuche den ganzen Tag schon, ihn zu beruhigen.\n\nErinnert mich an einen alten Mythos der Wildhämmer. Sturmkrähen wurden sie genannt. Und sie konnten nur von angesehenen Greifenreitern gebändigt werden.\n\nWenn wir ihm beweisen, dass Ihr den Geist des Sturms in Euch tragt, erwärmt er sich vielleicht für Euch. Versucht, Euch im Kampf zu beweisen.", sourceObjective = "Erschlagt mächtige Kreaturen der Dracheninseln und sammelt 50 Sturmgeister.", progress = "So ein sturer Greif ist mir noch nicht untergekommen!", completion = "Schau sich das einer an! Ich glaube, er mag Euch.\n\nHier, ich habe im Sattel der Sturmkrähe etwas Ausrüstung gefunden. Die sollte Euch perfekt passen! Und Ihr habt Euch definitiv verdient, etwas zu tragen, das einem Greifenreiter wie Euch gebührt.", sourceObjectiveStatus = "unverified-source-field" }
quests[81994] = { id = 81994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ehrwürdige Beziehung", description = "Aye, die Sturmkrähe findet langsam Gefallen an uns. Doch die Verbindung zwischen Reiter und Greif wird über viele Prüfungen hinweg geschmiedet.\n\nIhr mögt den Geist des Sturms in Euch haben, aber stellen wir zur Schau, wie Ihr ihn meistert. Es wird Zeit, Eure Fertigkeiten im Kampf wirklich zu beweisen.", sourceObjective = "Erschlagt mächtige Kreaturen der Dracheninseln und sammelt 500 Sturmgeister.", progress = "Ich glaube, der Greif vertraut mir allmählich.", completion = "Na, wenn das nicht was ist! Ihr habt wirklich gelernt, den Sturm in Euch zu meistern. Wenn das nicht beweist, was für ein herausragender Greifenreiter Ihr seid, dann weiß ich auch nicht.\n\nUnd das ist noch nicht alles. Wie ich sehe, strotzt die Rüstung, die ich Euch gegeben habe, jetzt vom Herz des Sturms! Interessant...", sourceObjectiveStatus = "unverified-source-field" }
quests[81999] = { id = 81999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neues Heim, neue Kerze!", description = "Janky hört, an der Oberfläche es geben riesige Feuerbienen.\n\nFeuerbienen machen Feuerwachs, oder? Was, wenn machen Kerzen aus Feuerbienenwachs? Wie das sein würde?\n\nJanky muss es wissen!", sourceObjective = "Trefft Janky im Aschenholtz.", completion = "Jetzt nur noch Wachs besorgen ohne sterben...", sourceObjectiveStatus = "unverified-source-field" }
quests[82007] = { id = 82007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt den Pfoten", description = "Die neugeborenen Luchse sind schon wieder abgehauen!\n\nDiese schelmischen Katzen treiben immer wieder Unfug und machen sich unbekümmert aus dem Staub. Da der Brummige verschwunden ist und nur Vesper und ich bleiben, um diese Position zu halten, wäre Eure Hilfe ein Segen!\n\nIch vermute, diese frechen Raubkatzen sind irgendwo in der Nähe. Versucht, sie zurückzubringen.\n\nIch würde mit einer Lampe die Höhle, das spinnenverseuchte Gebiet im Süden und die Küste im Norden absuchen.", sourceObjective = "Findet Bohnen, Rindfleisch, Donner und Käpt'n Elaena und bringt sie nach Attica Schnurrtal zurück.", progress = "Habt Ihr alle Katzen gefunden?", completion = "Wenn diese Katzen reden könnten, dann hätten sie sicherlich was zu erzählen!\n\nSieht so aus, als hätte eine Euch ins Herz geschlossen. Ich glaube, Ihr habt einen neuen Freund gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[82041] = { id = 82041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beledars Segen" }
quests[82042] = { id = 82042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugstein, Flugstein, jeder muss entdeckt sein", description = "Es ist so aufregend, in Valdrakken zu sein! Cuzolth und ich waren noch nie hier. Und es bietet wirklich alles, was wir uns erhofft hatten. Einige der anderen haben sich sogar vorgestellt. Sie haben uns tatsächlich für unsere Forschung zu den Flugsteinen und Wappen gedankt! Das ist der Traum jedes Forscherherzens!\n\nDeshalb brauche ich noch einmal Eure Hilfe. Könntet Ihr einige Flugsteine und ein neues Teil Abenteuerausrüstung auftreiben? Damit könnt Ihr dann zu Cuzolth kommen, um es aufzuwerten. Das würde uns wirklich helfen, unsere neue Position hier zu festigen.", sourceObjective = "Besorgt 50 Flugsteine, indem Ihr einzigartige Kreaturen besiegt, Dungeons und Schlachtzüge meistert, Weltquests abschließt oder Schätze plündert. Sprecht danach mit Cuzolth und wertet einen Ausrüstungsgegenstand aus Saison 4 unter Einsatz von Flugsteinen auf.", progress = "Es hat keine Eile. Aber vielleicht beeilt Ihr Euch trotzdem ein wenig...", completion = "Mein Freund! Ihr seid wie ein stützender Aufwind im Flug! Bitte nehmt dieses Zeichen meiner Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[82050] = { id = 82050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erweckte Wappen, unbegrenzte Möglichkeiten", description = "Eure Hilfe ist immer willkommen, und jetzt könnt Ihr Eure niedrigstufige Ausrüstung gleich hier aufwerten.\n\nAllerdings wisst Ihr vermutlich schon, dass Flugsteine auch ihre Grenzen haben. Um mächtige Abenteuerausrüstung aufzuwerten, braucht Ihr erweckte Wappen. Genau wie Flugsteine könnt Ihr diese Wappen bei vielen verschiedenen Aktivitäten erlangen. Erweckte Wappen gibt es in vier Stufen: je gefährlicher die Aufgabe, desto höher die Stufe des Wappens, das Ihr dafür bekommt.\n\nBringt mir doch 15 erweckte Wappen des Welpen, und wir können Euch helfen, Eure Ausrüstung weiter aufzuwerten.", sourceObjective = "Besorgt 15 erweckte Wappen des Welpen, indem Ihr einzigartige Kreaturen besiegt, Dungeons und Schlachtzüge bezwingt, Weltquests abschließt oder Schätze plündert. Kehrt dann zu Vaskarn in Valdrakken zurück.", progress = "Wenn Ihr Schwierigkeiten habt, verwitterte Vorbotenwappen zu finden, könnt Ihr in Khaz Algar oder diesen unterirdischen Gebieten, von denen ich gehört habe, nach versteckten Schätzen suchen. Da gibt es freilich jede Menge von diesen Schätzen!", completion = "Wunderbar. Ich freue mich schon, dass Ihr noch mächtiger werdet! Und natürlich, dass meine Forschung weiter vorangetrieben wird. Aber ja, machen wir Euch noch mächtiger!", sourceObjectiveStatus = "unverified-source-field" }
quests[82059] = { id = 82059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erweckte Wappen, unbegrenzte Möglichkeiten", description = "Eure Hilfe ist immer willkommen, und jetzt könnt Ihr Eure niedrigstufige Ausrüstung gleich hier aufwerten.\n\nAllerdings wisst Ihr vermutlich schon, dass Flugsteine auch ihre Grenzen haben. Um mächtige Abenteuerausrüstung aufzuwerten, braucht Ihr erweckte Wappen. Genau wie Flugsteine könnt Ihr diese Wappen bei vielen verschiedenen Aktivitäten erlangen. Erweckte Wappen gibt es in vier Stufen: je gefährlicher die Aufgabe, desto höher die Stufe des Wappens, das Ihr dafür bekommt.\n\nBringt mir doch 15 erweckte Wappen des Welpen, und wir können Euch helfen, Eure Ausrüstung weiter aufzuwerten.", sourceObjective = "Besorgt 15 erweckte Wappen des Welpen, indem Ihr einzigartige Kreaturen besiegt, Dungeons und Schlachtzüge bezwingt, Weltquests abschließt oder Schätze plündert. Kehrt dann zu Vaskarn in Valdrakken zurück.", progress = "Wenn Ihr diese geschnitzten Vorbotenwappen verliert, findet Ihr bei mächtigen Kreaturen um Khaz Algar weitere. Es soll die verschiedensten geben!", completion = "Na, ist das nicht toll?\n\nIch sage Bescheid, wenn ich weiß, wie man aus verwitterten Vorbotenwappen geschnitzte Vorbotenwappen machen kann. Nach meinen Erfahrungen mit anderen Wappen braucht man dazu mehr verwitterte Vorbotenwappen. Aber es ist einfach, Wappen zu schwächen!", sourceObjectiveStatus = "unverified-source-field" }
quests[82080] = { id = 82080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal Fackeln werfen", description = "Seid gegrüßt, <Feuerjongleur/Feuerjongleurin>! Macht es Euch Spaß, wenn Ihr Flammen wild umherwirbeln lasst? Das hört man doch gerne! Nun, haltet Ihr Euch für <einen Experten/eine Expertin> in Sachen Fackelwürfe? Dann will ich Euch auf die Probe stellen...\n\nIhr kennt die Regeln: Werft die Fackeln auf die markierten Kohlenpfannen. Doch dieses Mal geht es auf Zeit und es gilt VIEL mehr Kohlenpfannen zu treffen.\n\nBereit?", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", completion = "Wow, Ihr habt es geschafft! Spitze! Vielleicht könnt Ihr Euch nächstes Jahr für eine Stelle auf dem Fest bewerben!", sourceObjectiveStatus = "unverified-source-field" }
quests[82087] = { id = 82087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackelwurf", description = "Ihr wollt also <Feuerjongleur/Feuerjongleurin> werden? Denkt Ihr, dass Ihr das Zeug dazu habt? Die Geschicklichkeit? Die Reflexe? ...Den Mut? Wenn ja, dann wollen wir Euch mal auf die Probe stellen!\n\nStellt Euch neben das Feuer, dann seht Ihr Kohlenpfannen, über denen blinkende Markierungen schweben. Die müsst Ihr mit einer Fackel treffen. Seid schnell! Um für einen Wurf Punkte zu bekommen, müsst Ihr die Fackel werfen, bevor die Markierung verschwindet!\n\nTrefft genug markierte Kohlenpfannen und kommt dann hierher zurück... um Eure nächste Lektion zu erhalten.", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", progress = "Schnell! Wir haben keine Zeit zu verlieren!", completion = "Gut gemacht! Die Lunte eines Feuerkreisels brennt schnell... doch Ihr werdet die Kunst des Feuerjonglierens noch schneller erlernen! Nun macht Euch bereit! Beim nächsten Test werdet Ihr so richtig ins Schwitzen kommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[82088] = { id = 82088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobysskrawall" }
quests[82105] = { id = 82105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackelwurf", description = "Ihr wollt also <Feuerjongleur/Feuerjongleurin> werden? Denkt Ihr, dass Ihr das Zeug dazu habt? Die Geschicklichkeit? Die Reflexe? ...Den Mut? Wenn ja, dann wollen wir Euch mal auf die Probe stellen!\n\nWenn Ihr Euch dem Feuer nähert, seht Ihr Kohlenpfannen, über denen blinkende Markierungen schweben. Die müsst Ihr mit einer Fackel treffen. Seid schnell! Um für einen Wurf Punkte zu bekommen, müsst Ihr die Fackel werfen, bevor die Markierung verschwindet!\n\nTrefft genug markierte Kohlenpfannen und kommt dann hierher zurück... um Eure nächste Lektion zu erhalten.", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", progress = "Schnell! Wir haben keine Zeit zu verlieren!", completion = "Gut gemacht! Die Lunte eines Feuerkreisels brennt schnell... doch Ihr werdet die Kunst des Feuerjonglierens noch schneller erlernen! Nun macht Euch bereit! Beim nächsten Test werdet Ihr so richtig ins Schwitzen kommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[82109] = { id = 82109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal Fackeln werfen", description = "Seid gegrüßt, <Feuerjongleur/Feuerjongleurin>! Macht es Euch Spaß, wenn Ihr Flammen wild umherwirbeln lasst? Das hört man doch gerne! Nun, haltet Ihr Euch für <einen Experten/eine Expertin> in Sachen Fackelwürfe? Dann will ich Euch auf die Probe stellen...\n\nIhr kennt die Regeln: Werft die Fackeln auf die markierten Kohlenpfannen. Doch dieses Mal habt Ihr ein wenig mehr Zeit und VIEL mehr Kohlenpfannen zu treffen.\n\nBereit?", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", completion = "Wow, Ihr habt es geschafft! Spitze! Vielleicht könnt Ihr Euch nächstes Jahr für eine Stelle auf dem Fest bewerben!", sourceObjectiveStatus = "unverified-source-field" }
quests[82120] = { id = 82120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserreinigung" }
quests[82121] = { id = 82121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genugtuung verlangen", description = "Wir arbeiten nun schon seit einiger Zeit zusammen, {name}. Ich hoffe, Ihr respektiert meine Vision, was die Kunst der Kriegsführung angeht. Wie immer gibt es Regeln, die befolgt werden müssen. Grenzen, die nicht überschritten werden dürfen.\n\nZev'kall muss getötet werden, und ich muss es tun. Jeder Tag, an dem dieser Aufgestiegene Rüpel die Kriegsideale mit Füßen tritt, ist ein Schandfleck für unser Königreich.\n\nBitte, übernehmt diese letzte Aufgabe für mich. Reist zur feindlichen Festung und stellt diese Flagge auf ihren Stufen auf. Wir machen das richtig.", sourceObjective = "Platziert Anub'azals Standarte in der Belagerungsfeste in Azj-Kahet.", progress = "Beeilt Euch. Ich möchte diese Geschichte so schnell wie möglich beenden.", completion = "Nicht mal Zev'kall würde es wagen, eine formelle Herausforderung abzulehnen.\n\nGut.", sourceObjectiveStatus = "unverified-source-field" }
quests[82122] = { id = 82122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duell der Schicksale", description = "Ich bin kein Trottel, {name}. Zev'kall wird diese Herausforderung wohl nicht mal im Wortsinne ehren.\n\nWir befinden uns in der Festung des Feindes, umgeben von seinen zahllosen Schmeichlern. Es wird zu Störungen kommen.\n\nIch habe zwei Befehle für Euch, <Soldat/Soldatin>. Erstens werdet ihr alle Querulanten abwehren, die das Duell stören wollen. Und, was noch wichtiger ist, werdet Ihr zweitens weder Schwert noch Zauber gegen Zev'kall selbst einsetzen.\n\nMeine Klauen werden ihn töten.", sourceObjective = "Verteidigt Anub'azal gegen Zev'kalls Diener.", completion = "Es ist vollbracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[82123] = { id = 82123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verurteilung des Generals", description = "<Anub'azal würgt rau. Sekret fliegt ihm vom ausgerenkten Kiefer.>\n\nMeine Kohorte ist weiterhin den Durchtrennten Fäden verpflichtet. Ihr tätet gut daran, der Weberin zu berichten, was hier geschehen ist. Sie mag irritierend sein, aber ihr wird schon einfallen, wie es von hier aus weitergehen kann.", sourceObjective = "Informiert die Witwe Arak'nai über die Ereignisse.", completion = "Das ist also passiert.\n\nVerfluchter Narr, was hat er sich nur gedacht? Dennoch... Zev'kalls Tod ist ein schwerer Schlag für die Loyalisten. Anub'azal ist ein Chitinkopf, aber er ist auch stark.\n\nSeine Nachkommen führen seine Arbeit für die Fäden fort, und man wird sich an ihn als vorzüglichen General erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[82124] = { id = 82124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anfang vom Ende", description = "Königin Ansurek war seit dem Mordversuch sehr fleißig. Sie hat Azj-Kahet jetzt noch stärker unter Kontrolle, und ihre loyalen Adligen kümmern sich um jede ihrer düsteren Launen. \n\nAuf Geheiß der Königin haben ihre ergebensten Adligen, Strangspinner Takazj und Anub'arash, den Umbralbasar abgeriegelt. \n\nTakazjs unerträglichen Propagandatricks und Anub'arashs erhöhte Militärpräsenz haben eins ganz deutlich gezeigt: Steigt auf oder sterbt. \n\n Ihr müsst für mich zum Umbralbasar gehen und ihren Einfluss dort stören.", sourceObjective = "Sorgt auf dem Umbralbasar für Verwirrung.", progress = "Wie enttäuschend, dass uns Königin Ansurek weiterhin in die Dunkelheit führt.", completion = "Der Griff der Königin lockert sich, und Strangspinnerin Takazj und Anub'arash stehen in ihren Augen schlechter da. Zwei Fliegen, ein Faden.", sourceObjectiveStatus = "unverified-source-field" }
quests[82125] = { id = 82125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Spion wie wir", description = "Es gibt verstörende Nachrichten aus dem Bau: Ein düsterer Plan entfaltet sich in der Gosse unter uns. Die Bürger des Distrikts verschwinden in einem alarmierenden Tempo.\n\nStrangspinnerin Takazj und Anub'arash sind so subtil wie eine Axt, deswegen bezweifle ich, dass dies deren Werk ist. Hier hat jemand seine Finger im Spiel, der wesentlich subtiler vorgeht.\n\nIch habe einen Kontakt im Bau. Er heißt Gut'usul. Trefft Euch mit ihm im Bau und findet heraus, was da unten vor sich geht.", sourceObjective = "Trefft Euch mit Gut'usul im Bau.", completion = "Höchste Zeit, dass jemand zum Helfen kommt. Der Wesir schickt Euch, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[82126] = { id = 82126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung des Volks", description = "Der Wesir hat Euch sicher schon die Einzelheiten erklärt. Bürger des Baus werden vermisst. So viel wisst Ihr.\n\nAber das Flüstern im Wind erzählt eine viel größere Geschichte. Unsere Bürger werden ins Transformatorium gebracht und kehren nie zurück!\n\nWir müssen das um jeden Preis stoppen. Es wurden noch mehr Bürger verschleppt, aber es ist noch nicht zu spät für sie. Sie werden immer noch im Bau festgehalten. Findet sie und befreit sie.", sourceObjective = "Befreit 5 Bürger im Bau.", progress = "Rasch. Nicht lange, und wir können sie nicht mehr erreichen.", completion = "Die Bürger des Baus stehen in Eurer Schuld. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[82127] = { id = 82127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jäger wird zur Beute", description = "Diese Entführer schnappen sich immer mehr Bürger, und niemand im Bau kann sie aufhalten. Es wird langsam Zeit, dass jemand etwas dagegen unternimmt. \n\nSie schleichen durch den Bau und glauben, dass niemand sie sieht, aber ich kann sie sehen, wir alle können sie sehen. Das Problem ist, dass es keiner hier mit ihnen aufnehmen kann. Und da kommt Ihr ins Spiel.\n\nMacht Jagd auf diese Entführer und zeigt ihnen, wer hier die wahre Beute ist.", sourceObjective = "Tötet 8 Entführer im Bau.", completion = "Hoffentlich haben sie sich gewunden, als sie starben. Ich habe kein Mitleid mit Leuten, die sich gegen ihresgleichen wenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[82130] = { id = 82130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spitze im Visier", description = "Während Ihr unterwegs wart, war ich ebenfalls nicht untätig. \n\nEure Heldentaten im Bau haben die Aufmerksamkeit von jemandem ganz oben auf sich gezogen. Ein seltsames, in Bandagen gewickeltes Wesen, an dem der Gestank der Verzweiflung hing.\n\nZum Glück stattet dieses ungewöhnliche Monster dem Bau einen Besuch ab, um herauszufinden, wieso ihre Entführer verschwunden sind. Das ist Eure Chance, zuzuschlagen und deren gesamte Operation auszuschalten.", sourceObjective = "Tötet den Meister-Entführer.", progress = "Bald wird der Bau frei sein.", completion = "Die Kunde von Euren Taten eilt Euch voraus. Ein Zeichen für gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[82133] = { id = 82133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokumentation: Feldhandbuchausgabe" }
quests[82141] = { id = 82141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mord an einer Königin", description = "Dass sie ihre Kontrolle über die Bürger ausweiten würde, hatte ich von der Königin erwartet, aber die Bürger des Baus gewaltsam aufsteigen zu lassen, das geht zu weit.\n\nKönigin Ansurek ist viel tiefer gefallen, als ich mir jemals hätte vorstellen können. Ich kann nicht einfach dasitzen und zusehen, während sie unser Volk in den Ruin führt.\n\nJetzt oder nie! Wir müssen Königin Ansurek töten und unser Volk in eine bessere Zukunft führen. Wer weiß, wie tief sie sonst noch sinken wird.", sourceObjective = "Tötet Königin Ansurek.", progress = "Es betrübt mich, dass es so weit gekommen ist.", completion = "Regizid ist nicht meine Sache, aber es musste getan werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[82143] = { id = 82143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Dissonanz", description = "Hannan hat recht, meine Gegenwart hier ist nicht unbedingt gestattet.\n\nDoch diese Verderbnis hallt in meinem Geist wider wie ein dissonanter Akkord im ansonsten reinen Lied der Welt. Wie ein Hilfeschrei.\n\nIch muss dem Ruf folgen. Ich muss der Dissonanz zum Ursprung folgen und das Herz finden, um es reinigen zu können.\n\nHelft mir.", sourceObjective = "Trefft Orweyna und Hannan vor der Salinengossenhöhle.", progress = "Ihr habt Euch als hilfreich erwiesen. Ich bin sicher, wir finden eine Möglichkeit, alle Extraktoren zu eliminieren, die wir finden.", completion = "<Orweyna blickt besorgt zur Höhle.>\n\nAls er zugestimmt hat, mit mir zu kommen ... Ich sollte ihn beschützen. Dafür sorgen, dass nichts Schlimmes passiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[82144] = { id = 82144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterwegs", description = "Das ist die einzige Straße zum Aufzug. Er hätte längst hier sein müssen. \n\nEs sei denn... er hat nicht die Straße genommen! Er möchte nicht entdeckt werden. \n\nEr hat keine Ahnung, wie gefährlich die Tiefen sein können. Wir müssen ihn finden!", sourceObjective = "Findet Brennok.", completion = "Hätte er es mir doch eher gesagt... dieser steinköpfige Tölpel. Aber wenn er wirklich die Welt entdecken will, braucht er Anleitung. So auf sich allein gestellt weiß er sicher nicht mal, wie er einen Fuß vor den anderen setzen soll.\n\nSeine Chronik ist bereits mit einem Raben unterwegs nach Gundargaz. Dort kümmern sie sich um seine Geschichten. Zumindest so lange, bis er genug von Abenteuern hat.\n\nMein Eid ist und bleibt, wie er immer lautete: mich um ihn zu kümmern. Wenn ich ihn hier unten festhalte, werde ich diesem Eid nicht gerecht.\n\nVielen Dank, dass Ihr ihm geholfen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[82145] = { id = 82145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Mooswolle" }
quests[82146] = { id = 82146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Glutbienenansturm" }
quests[82153] = { id = 82153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaften und Gesandte", description = "Wir segelten eine gefühlte Ewigkeit lang. Ich muss eingestehen, dass ich manchmal Sorge hatte, dass wir zu spät kommen.\n\nAber Euch alle vereint und stark zu sehen, hat meine Hoffnung neu entfacht.\n\nBevor wir mit der Planung beginnen, müssen wir hier in Dornogal eine Operationsbasis einrichten.", sourceObjective = "Richtet die Botschaft Eurer Fraktion in Dornogal ein.", completion = "Wollt Ihr damit sagen, dass Ihr die ganze Zeit Inneneinrichter wart und mir etwas vorenthalten habt?\n\nSehr schön, {name}.\n\nIhr werdet meine Räumlichkeiten neu einrichten, wenn wir heimkehren. Ja, das werdet Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[82154] = { id = 82154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Titanischer Rückstrom" }
quests[82155] = { id = 82155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Schatten der Tiefe" }
quests[82156] = { id = 82156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Wenn die Tiefen sich regen" }
