quests[82164] = { id = 82164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseelenerinnerung: Herrschaft der Alten Götter" }
quests[82195] = { id = 82195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rost und Reue", description = "Als Ihr Euch nähert, fällt Euch ein rostiger Hebel auf, der stur festklemmt.\n\n\"Das Ding hat sich seit Ewigkeiten nicht mehr bewegt\", denkt Ihr Euch, als das raue Metall keinen Millimeter nachgibt.\n\nIhr seht Euch um und bemerkt den öligen Film der pflanzenähnlichen Krabbler, die sich in der Nähe tummeln. \"Vielleicht würde ein wenig natürliches Gleitmittel Abhilfe schaffen\", überlegt Ihr, als Ihr erkennt, dass diese unfreundliche Flora Euch womöglich genau das bietet, was Ihr zum Lockern des Hebels benötigt.", sourceObjective = "Sammelt 3 reine Kriecherextrakte von Untertropfenkrabblern und Krabblersprösslingen in den Schallenden Tiefen.", progress = "Der Hebel verharrt an Ort und Stelle, seine Geheimisse ohne die Kriecherextrakte für immer hinter Schloss und Hebel.", completion = "Ausgestattet mit frischem Kriecherextrakt nähert Ihr Euch dem störrischen Hebel auf Neue.\n\nEinige Tropfen der zähen Flüssigkeit und... der Hebel bewegt sich mit Leichtigkeit und offenbart neue Pfade vorwärts!", sourceObjectiveStatus = "unverified-source-field" }
quests[82197] = { id = 82197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reservenremmidemmi" }
quests[82206] = { id = 82206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Schatten" }
quests[82207] = { id = 82207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseelenerinnerung: Abkömmling entfernter Wasser" }
quests[82212] = { id = 82212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwacher Löwenfisch" }
quests[82213] = { id = 82213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine flattrige Bitte", description = "Ich werde eine Auswahl unserer wichtigsten Handelsgüter zusammentragen, bevor wir zum Treffen aufbrechen. Aber ich könnte etwas Hilfe gebrauchen, um ein paar zusätzliche Gegenstände zu sammeln. \n\nIn letzter Zeit haben wir Probleme, richtig gutes Fledermausfleisch in Heilsturz zu bekommen. Könntet Ihr welches sammeln, bevor Ihr nach Dunelles Güte kommt?", sourceObjective = "Sammelt 8 Fesselzahnblattnasenfleisch.", progress = "Habt Ihr das Fleisch?", completion = "Großartig. Wir hatten nicht die Ressourcen, um Leute zum Fleischsammeln von der Mauer zu holen bei all den Wespen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82214] = { id = 82214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mag irgendwer Wespen?", description = "Es ist uns nicht gelungen, in diesem Gebiet Ressourcen zu sammeln, weil Hornissen eingezogen sind.\n\nWir konnten einfach keine Ressourcen von der Mauer entbehren, um sie zu bekämpfen. Wenn Ihr das übernehmen könntet, wären wir alle sehr dankbar.", sourceObjective = "Tötet 10 Fesselzahnhornissen.", completion = "Danke, {name}.\n\nIch hasse diese Biester. Wirklich, wer hält denn Wespen groß wie Luchse für eine gute Idee?", sourceObjectiveStatus = "unverified-source-field" }
quests[82215] = { id = 82215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewöhnliche Fasern", description = "Es gibt eine Pflanzenfaser, die in Schmuggelstieg und in den Fängen wächst, und aus der man ein hervorragendes Seil herstellen kann. Wegen der Hornissen konnten wir sie lange nicht sammeln und unsere Vorräte gehen zur Neige.\n\nWenn Ihr in der Gegend seid, könntet Ihr welche sammeln?", sourceObjective = "Sammelt 5 robuste Efeufasern.", progress = "Diese Fasern sind zauberhaft. Die Seile werden stabil und doch geschmeidig.", completion = "Ob Euer Volk an diesen Fasern interessiert ist?\n\nMan kann daraus die besten Seile machen, die ich kenne.", sourceObjectiveStatus = "unverified-source-field" }
quests[82216] = { id = 82216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ökonomische Bitte", description = "Ich habe gehört, Ihr kommt von der Oberfläche? Seid Ihr den Irdenen begegnet?\n\nFrüher haben wir mit ihnen Handel getrieben, aber nach dem Tag der Dunkelheit hatten wir Schwierigkeiten, Gesandte auszusenden. Die, die wir schickten, kamen nie zurück. Ehrlich gesagt, dachten wir, sie seien umgekommen.\n\nIch werde versuchen, sie noch einmal zu kontaktieren. Ich möchte, dass Ihr eine Empfehlung schreibt, für den Fall, dass wir sie irgendwie beleidigt haben sollten.", sourceObjective = "Schreibt ein Empfehlungsschreiben in Mereldar in Heilsturz.", progress = "Ich hoffe, dass das gut geht. Wir benötigen wirklich zusätzliche Ressourcen.", completion = "Habt Dank, ich werde einen Läufer damit zu den Irdenen schicken. Ich bete, dass sie es gesund zurückschaffen.\n\nUnd vielen Dank für die Informationen, wie man mit Eurem Volk handelt. Ich hoffe, dass sie ebenfalls teilnehmen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[82217] = { id = 82217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untergrundwirtschaft", description = "Nach dem Tag der Dunkelheit haben wir von dem Irdenen weder etwas gesehen noch gehört. Ich weiß nicht, wieso.\n\nWir haben uns eigentlich gut verstanden. Ich habe Merrix sogar als Freund angesehen, wenn auch als einen seltsamen. \n\nDas muss unbedingt gut gehen.", sourceObjective = "Helft den Arathi bei den Handelsgesprächen in Dunelles Güte.", progress = "Dieser Handel muss klappen.", completion = "Mögen die Flammen mich bewahren. Das lief besser als erhofft.\n\nIch danke Euch. Ihr habt uns einen großen Gefallen getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[82219] = { id = 82219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt Würze ins Leben", description = "Die Flamme grüßt Euch, {name}.\n\nDer Handel läuft gut, seit die Schallenden Tiefen wieder sicher sind und die Dinge sich einigermaßen beruhigt haben. Trotzdem kann unsere Generalin noch nicht aufatmen. Sie ist angespannt, und das ist nicht gesund. Eine kranke Generalin führt zu einer kranken Armee. \n\nAlso ist es Zeit für einen Tag mit der Familie. Könnt Ihr einige Kräuter für das Essen sammeln? Ihr solltet die großen nehmen, ignoriert die kleinen.", sourceObjective = "Sammelt 7 Lichtgebadete Lotus in Heilsturz.", progress = "Kräuter aus dem Licht Beledars schmecken fantastisch.", completion = "Die sind hervorragend, gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[82220] = { id = 82220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adler sieht, Adler stirbt", description = "Die Adler draußen beim Untermeer haben im Licht von Beledar gebadet, und das macht sie besonders schmackhaft.\n\nKönntet Ihr ein paar Adlerfilets beschaffen? Nehmt diese Harpune mit, denn sie können recht angriffslustig sein.", sourceObjective = "Sammelt 5 Adlerfilets.", progress = "Passt auf Euch auf. Die Adler können Euch leicht verletzen.", completion = "Die sehen sehr saftig aus. Danke, {name}!\n\nIch sorge dafür, dass daraus eine gute Mahlzeit für uns wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[82221] = { id = 82221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vollständig angezogen", description = "Ein traditionelles Familienessen der Arathi beinhaltet die Zurschaustellung verschiedener Medaillen, Auszeichnungen und Andenken der Familie. Wenn man bedenkt, wie erfolgreich die Karriere meiner Mutter war, dann dürfte das eine Weile dauern. \n\nWürdet Ihr bei den Dekorationen mithelfen?", sourceObjective = "Helft Familie Stahlstoß, ihr Haus in Mereldar für das bevorstehende Mahl zu schmücken.", progress = "Das Essen muss gut werden, meine Mutter muss sich entspannen.", completion = "Danke. Dies sind sehr geschichtsträchtige Objekte. Wie schön, sie ausgestellt zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82222] = { id = 82222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochen mit Finesse", description = "Es tut mir leid, dass meine Tochter Euch da mit reingezogen hat. Ihr hättet sicher Besseres zu tun.\n\nSie hat schreckliche Manieren. Ich werde mich mal mit denjenigen unterhalten müssen, die sie großgezogen haben.\n\n<Der Mund der Generalin verzieht sich zu einem kurzen Grinsen.>\n\nAber Ihr seid hier. Möchtet Ihr Euch einer angenehmeren Aktivität anschließen? Wir fangen gleich mit dem Kochen an.", sourceObjective = "Helft Familie Stahlstoß in Mereldar beim Kochen.", progress = "Wieso eine Prise Salz und keine Handvoll? Je mehr Zutaten, desto besser.", completion = "Hah! Alle Flammen, ich hatte ganz vergessen, wie viel Spaß das Kochen macht!\n\nDas hatte ich wirklich nötig.", sourceObjectiveStatus = "unverified-source-field" }
quests[82223] = { id = 82223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein selbstgemachtes Mahl", description = "Selbstgemachter Eintopf. Auf der ganzen Welt gibt es nichts Besseres. \n\nEr ist vielleicht nicht so lecker wie der Eintopf aus dem Gasthaus \"Reichesrand\", aber dafür wurde er von der Familie zubereitet. Das macht ihn so großartig.\n\nSetzt Euch zu uns. Ihr habt es mehr als verdient.", sourceObjective = "Esst eine Mahlzeit im Stahlstoßanwesen in Mereldar in Heilsturz.", progress = "Lange her, dass ich zuletzt mit der ganzen Familie gegessen habe.", completion = "Ah, das brauchte ich.\n\nIhr seid uns jederzeit willkommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[82224] = { id = 82224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht nach dem Kompilator.", description = "Das wäre alles hier oben. Könntet Ihr mal nach Brennok sehen? Rezitationen können anstrengend sein und ich bin sicher, dass er die Hilfe zu schätzen weiß.", sourceObjective = "Seht nach Brennok.", completion = "Ich wollte gerade nach Euch suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82225] = { id = 82225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabungsspektakel" }
quests[82226] = { id = 82226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Papiere? Bitte!", description = "Hey, Kumpel, was ist nötig, damit Ihr mir ein bisschen Ruhe gönnt?\n\nWie wärs mit einem neuen Posten? Einem SPITZENPOSTEN!\n\nIch hab Boss Funkelschuss versprochen, dass ich die Arbeiter... äh, ...unterkünfte besetze. Ja, genau, dass ich den Schalter an den Unterkünften besetze.\n\nWürdet Ihr hier solange die Stellung halten? Ist wirklich nur der alltägliche Papierkram. Dokumente prüfen, Wirtschaftssabotage verhindern, ab und zu einen Luftangriff anordnen, das Übliche eben...\n\n<Garv ist schon wieder eingeschlafen.>", sourceObjective = "Überprüft die Papiere am Schreibtisch des Aufsehers an der Chancenspitze.", progress = "Ihr steht mir im Schatten, Kumpel.", completion = "<Garv bewirft Euch mit etwas, ohne aufzusehen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[82229] = { id = 82229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ungewöhnliche Bitte", description = "{name}, willkommen in Bel'ameth. Ich überlege gerade... Habt Ihr vielleicht Zeit für einen kleinen Gefallen?\n\nHeute früh suchte mich eine junge Kaldorei namens Kelestra auf. Sie bat um Erlaubnis, ihre Familie in einem Grabhügel zu bestatten. Eine ungewöhnliche Bitte, doch ich gab ihr meinen Segen und wies sie zum Hügel der Tagträume.\n\nSie wirkte... melancholisch. Erst als sie weg war, fiel mir ein, dass sie womöglich die letzte Überlebende aus ihrer Familie ist. Wenn Ihr einen Moment Zeit habt, würdet Ihr wohl nach ihr sehen?", sourceObjective = "Seht nach Kelestra im Hügel der Tagträume.", completion = "<Kelestra ist so in Gedanken versunken, dass es ein bisschen dauert, bis sie auf Euch aufmerksam wird.>\n\nOh, hallo. Ich habe Euch gar nicht bemerkt. Würde es Euch... Habt Ihr vielleicht einen Moment?", sourceObjectiveStatus = "unverified-source-field" }
quests[82234] = { id = 82234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für jeden Widder ein florales Flair" }
quests[82236] = { id = 82236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test" }
quests[82237] = { id = 82237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Fall hinauf" }
