quests[82245] = { id = 82245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundlicher Thak" }
quests[82248] = { id = 82248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorstoß zu Faerin", description = "Ich habe einen kleinen Leckerbissen aus einer Ecke meines Netzes, noch schön eingewickelt. Soll ich ihn mit Euch teilen? Er wird sicher Euren Untergang bedeuten, {race}.\n\nNun gut... Ich kann Eure Ungeduld förmlich riechen. Ich habe den kleinen grünen Kobold, den Ihr Gazlowe nennt, in den Nordosten geschickt. Er berichtet mir, dass die Königin und der General ihre Elite-Sturmtruppen versammeln. Zweifellos bereiten sie sich darauf vor, in Heilsturz einzumarschieren.\n\nVerschwindet zu Eurer Freundin, der Lampenanzünderin. Sie wird bestimmt alles in Sichtweite zerstören wollen.", sourceObjective = "Sprecht mit Faerin Lothar in Faerins Vorstoß.", completion = "Die Weberin schickt Euch direkt? Das macht mich umso besorgter.", sourceObjectiveStatus = "unverified-source-field" }
quests[82254] = { id = 82254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aquakalypse" }
quests[82256] = { id = 82256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kreaturen des Katarakts einfangen" }
