quests[82263] = { id = 82263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseelenerinnerung: Elementarer Zorn" }
quests[82266] = { id = 82266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turmwaschsimulator" }
quests[82268] = { id = 82268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die reuevolle Heimreise", description = "Ich habe vor, den Brustpanzer von Ryton und den Zunderkasten von Sir Aschenreich in Mereldar zu verbrennen. Es wäre mir eine Ehre, wenn Ihr Euch mir anschließen würdet.\n\nWürdet Ihr den Brustpanzer dorthin tragen?", sourceObjective = "Erweist Faerin die Ehre, Ryton Schwarzholms Brustplatte nach Mereldar in Heilsturz zu bringen.", progress = "Habt Dank dafür, {name}.", completion = "Ihr habt den Arathi heute einen großen Dienst erwiesen. Bitte bleibt und helft uns, Ryton und Sir Aschenreich unseren Respekt zu zollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82284] = { id = 82284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedenken an die Gefallenen", description = "Es ist Brauch bei uns, den Gefallenen Respekt zu erweisen, indem wir ihre Habseligkeiten verbrennen. Meist ihre Zunderkästen, da sie einfacher zu transportieren sind. Diese Gegenstände übergeben wir den Flammen.\n\nWir haben den Zunderkasten von Sir Aschenreich, und Rytons Brustplatte wird sein Andenken ehren.\n\nIhr habt nicht nur für mich, sondern auch für Heilsturz Euer Leben riskiert. Ich wäre geehrt, wenn Ihr mir ein letztes Mal helfen würdet, um unserer Gefallenen zu gedenken.", sourceObjective = "Platziert Brustplatte und Zunderkasten im Schmiedefeuer in Mereldar.", progress = "Danke, {name}.", completion = "Es ist vollbracht. Merkwürdig, aber auch irgendwie tröstlich, endlich Gewissheit über das Schicksal meines lieben Freundes zu haben.\n\nVielen Dank für alles, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[82285] = { id = 82285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseelenerinnerung: Eine verwundete Seele" }
quests[82286] = { id = 82286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseelenerinnerung: Verlassene Alte Götter" }
