quests[82296] = { id = 82296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Schöpfung", sourceObjective = "Ah, der Katalysator. Er ist ein Wunder, das sich nur schwer in Worte fassen lässt.\n\nEs ist so: Lange bevor der Grundstein für unsere Stadt gelegt wurde, durchstreiften Titanen dieses Land. Sie waren Meister der Innovation und fabrizierten Wunder jenseits aller Vorstellungskraft. Als eins ihrer großen Werke schufen sie den Katalysator.\n\nUnd nun gehört seine Macht Euch.", sourceObjectiveStatus = "unverified-source-field" }
