quests[82335] = { id = 82335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristalle", sourceObjective = "Die Arathi wissen Eure Hilfe in diesen gefährlichen Landen wirklich zu schätzen. Nehmt dies bitte als Zeichen unserer Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[82338] = { id = 82338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftrag in Abwesenheit", description = "Erinnert Ihr Euch an das Logbuch aus Zev'kalls Büro? Es enthielt wichtige Informationen über seinen Missbrauch an unserem Volk. Ich habe es meinem Assistenten Anub'okki gegeben, damit es zu den Historikern in den Strängen gelangt.\n\nIch habe nichts von Anub'okki gehört. Vermutlich stimmt etwas nicht. Hört euch in den Strängen um, ob ihn jemand gesehen hat.", sourceObjective = "Sucht Anub'azals Schüler in den Strängen von Nerub'ar.", completion = "Lasst uns reden, aber wir müssen leise sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[82339] = { id = 82339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ehrloser Mord", description = "Wenn Ihr dann schneller hier verschwindet, sage ich Euch, was ich gesehen habe.\n\nIch habe nicht gesehen, was mit Anub'okki geschehen ist. Aber ich kann Euch sagen, dass die Leichen im Stütznest Xesh abgeladen werden, um in Vergessenheit zu geraten. Anub'okki wurde vor gar nicht allzu langer Zeit weggebracht. \n\nWenn Ihr Euch beeilt, könnt Ihr die Überreste noch begutachten, bevor sie verschwunden sind.", sourceObjective = "Holt das Logbuch zurück und bringt in Erfahrung, was mit Anub'okki passiert ist.", progress = "Habt Ihr Anub'okki gefunden?", completion = "Dieser Dolch trägt eine Version von Zev'kalls neuen Pheromonen am Griff. Ich weiß, dass er in die Sache verwickelt ist. Mit dem direkten Mord an Anub'okki ist er einen Schritt zu weit gegangen.\n\nDer Assassine hat außerdem das Logbuch nicht wieder an sich genommen. Zev'kall legt seine Karten auf den Tisch: Er glaubt, ich wäre machtlos, selbst wenn ich das Erpressung für eine Erpressung habe.\n\nDas wird er bereuen!", sourceObjectiveStatus = "unverified-source-field" }
quests[82340] = { id = 82340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gliedmaßenverlust", description = "Fröhliche Grüße! Ich bin Herr Sonnenblume und dies ist meine Teestube, die ich auch als Behandlungszimmer nutze. Ein sicherer Ort für jeden!\n\nIch frage mich, ob Ihr auch einem meiner Patienten helfen würdet. Vi'azl hat eine Todesangst vor Kreaturen mit weniger Gliedmaßen als üblich. Ich glaube, diese Angst hat sich zu einer krankhaften Phobie gegen Verstümmelung entwickelt. Ich versuche, diesem Phänomen auf den Grund zu gehen.\n\nWürdet Ihr mit ihm sprechen und ihm beweisen, dass man sich vor Euch, einer Person mit weniger als acht Beinen, nicht fürchten muss?", sourceObjective = "Helft Herrn Sonnenblume bei Vi'azls Therapiestunde.", progress = "Vi'azl muss ein entsetzliches Trauma haben, das mit Kreaturen mit weniger Gliedmaßen zusammenhängt. Wir müssen ihm helfen.", completion = "Oh je. Das ist noch viel schlimmer, als ich ursprünglich diagnostiziert hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[82342] = { id = 82342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleines Bündel voller Waren", sourceObjective = "Aufgabe abgeschlossen. Der Rat belohnt Euch für Eure Hilfe bei der Wiedervereinigung der Irdenen.", sourceObjectiveStatus = "unverified-source-field" }
