quests[82365] = { id = 82365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkerfreude", sourceObjective = "Ihr seid eine geschätzte Bereicherung für den Rat, {name}. Bitte nehmt dieses Zeichen unserer Dankbarkeit an, auf dass Ihr jetzt und immerdar als Ehrenratsmitglied bekannt sein möget.", sourceObjectiveStatus = "unverified-source-field" }
quests[82366] = { id = 82366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NICHT BENUTZEN" }
quests[82367] = { id = 82367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdverkrusteter Edelstein", sourceObjective = "Dankbarkeit wird ausgedrückt. Bitte nehmt dies als Belohnung für all Eure harte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[82368] = { id = 82368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NICHT BENUTZEN" }
quests[82369] = { id = 82369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strahlendes Bündel voller Waren", sourceObjective = "So hilfreich! Kobolde danken Euch. Irdene danken Euch. Die Versammlung dankt Euch! \n\nKerze für Euch! Keine bessere Belohnung als das!\n\nNein, diese Kerze nicht aus Ohrenschmalz gemacht. Ist aus Bienenwachs! Riecht so gut! Ihr mögt schöne Gerüche, ja? Wenn nicht, wollt Ihr vielleicht von mir weggehen, ha, ha, ha! Entschuldigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[82370] = { id = 82370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappen", sourceObjective = "Dankbarkeit wird ausgedrückt. Bitte nehmt dies als Belohnung für all Eure harte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[82371] = { id = 82371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flackernde Kerze", sourceObjective = "So hilfreich! Kobolde danken Euch. Irdene danken Euch. Die Versammlung dankt Euch! \n\nKerze für Euch! Keine bessere Belohnung als das!\n\nJa, diese Kerze ist aus meinem eigenen Ohrenschmalz. Ihr? Besonders. Und \"gern geschehen\". Vielleicht kann ich nächstes Mal etwas von Eurem Ohrenschmalz haben? Denkt darüber nach! Ich warte.", sourceObjectiveStatus = "unverified-source-field" }
